using UnityEngine;
namespace BWVR {
public sealed partial class WorldBrush {
 public const float GiftCost=6;GameObject[] foodGifts,woodGifts;float[] giftUntil=new float[6];Vector3[] giftPoint=new Vector3[6],giftScale=new Vector3[6];int giftSlot;SliceState giftSeason;
 public int LastGiftWitnesses{get;private set;}
 public bool GiftReady=>Season.Hybrid.time>=resources.State.nextProvisionAt;
 void BuildProvisions(){foodGifts=new GameObject[3];woodGifts=new GameObject[3];for(int i=0;i<3;i++){foodGifts[i]=resources.CreateLoad(VillageResource.Wheat);woodGifts[i]=resources.CreateLoad(VillageResource.Wood);giftScale[i]=foodGifts[i].transform.localScale;giftScale[i+3]=woodGifts[i].transform.localScale;foreach(var go in new[]{foodGifts[i],woodGifts[i]}){go.name="Delivered provision display";foreach(var c in go.GetComponentsInChildren<Collider>()){c.enabled=false;Destroy(c);}go.SetActive(false);}}}
 void Update(){if(foodGifts==null)return;if(giftSeason!=Season){foreach(var go in foodGifts)go.SetActive(false);foreach(var go in woodGifts)go.SetActive(false);System.Array.Clear(giftUntil,0,giftUntil.Length);giftSeason=Season;}for(int i=0;i<6;i++){var go=i<3?foodGifts[i]:woodGifts[i-3];if(!go.activeSelf)continue;float remaining=giftUntil[i]-Season.Hybrid.time;if(remaining<=0){go.SetActive(false);continue;}float size=Mathf.Min(1,(4-remaining)*4,remaining*2);go.transform.localScale=giftScale[i]*Mathf.Max(.05f,size);go.transform.position=giftPoint[i]+Vector3.up*nav.Scale*((i<3?.6f:.1f)+Mathf.Sin((4-remaining)*Mathf.PI)*.1f);}}
 public bool CanGift(Vector3 point,bool food,out string reason){EnsureSeason();reason="";if(Season.paused||miracles.Suspended){reason="Paused";return false;}if(!miracles.CanAfford(GiftCost)){reason="Not enough spiritual energy";return false;}return resources.CanReceiveProvision(point,food?VillageResource.Wheat:VillageResource.Wood,out reason);}
 public bool GiftPulse(Vector3 point,bool food){EnsureSeason();if(!GiftReady){Reason="Giving the previous gift";return false;}if(!CanGift(point,food,out var reason)){Reason=reason;return false;}var kind=food?VillageResource.Wheat:VillageResource.Wood;float nominal=food?3:2;float amount=resources.State.ReceiveProvision(kind,Mathf.Min(nominal,resources.ProvisionSpace(kind)),Season.Hybrid.time);if(amount<=0){Reason="No storage space for this gift";return false;}miracles.SpendEnergy(GiftCost);LastGiftWitnesses=resources.WitnessProvision(point,amount/nominal);resources.Refresh();
  if(giftSeason!=Season){foreach(var go in foodGifts)go.SetActive(false);foreach(var go in woodGifts)go.SetActive(false);giftSeason=Season;}int slot=giftSlot++%3;var display=food?foodGifts[slot]:woodGifts[slot];int index=food?slot:slot+3;giftPoint[index]=point;giftUntil[index]=Season.Hybrid.time+4;display.transform.position=point;display.transform.localScale=giftScale[index]*.1f;display.SetActive(true);Point=point;Reason="";Pulses++;creature.InvalidateLesson("Player provisions are not creature work");Season.Hybrid.Evidence.Add(Season.Hybrid.time,EvidenceKind.Provision,EvidenceSource.PlayerPlacement,CreatureAction.IdleOrObserve,food?"food-gift":"wood-gift",amount.ToString("0.0")+" supplies; "+LastGiftWitnesses+" religious witnesses");IslandAudio.Cue(IslandSound.Discovery,point,GetEntityId().GetHashCode(),.5f);return true;
 }
 public bool ProcessGift(Vector3 point,bool food,bool held,float dt,bool aimValid=true){EnsureSeason();StopRain();StopWind();if(!held||Season.paused||miracles.Suspended||!HybridState.Number(dt,0,1)){Stop();return false;}if(!miracles.CanAfford(GiftCost)){restRequired=true;Reason="Release the trigger: energy exhausted";return false;}if(restRequired)return false;if(!aimValid)return false;return GiftReady&&GiftPulse(point,food);}
}
}
